import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation to efficiently test membership of an item in a set with a 
    configurable false positive rate. The implementation uses hash functions and a bit array 
    for storage without external libraries.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(expected_items, self.size)
        self.bit_array = [0] * self.size

    def _optimal_size(self, n: int, p: float) -> int:
        """Calculates the optimal size of the bit array."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, n: int, m: int) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generates a list of hash values for the item."""
        hash_values = []
        for i in range(self.hash_count):
            hash_value = int(hashlib.sha256((item + str(i)).encode()).hexdigest(), 16) % self.size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Adds an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item is possibly in the Bloom Filter."""
        for hash_value in self._hashes(item):
            if self.bit_array[hash_value] == 0:
                return False
        return True

