class BloomFilter:
    """
    A Bloom Filter implementation to test set membership with a specified 
    false positive rate. It uses a bit array to store data and multiple 
    hash functions to minimize collisions.

    Attributes:
    - bit_array: List of booleans representing the bit array.
    - size: The optimal size of the bit array.
    - hash_count: The number of hash functions used for adding items.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        if false_positive_rate <= 0 or false_positive_rate >= 1:
            raise ValueError("False positive rate must be between 0 and 1.")

        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(self.size, expected_items)
        self.bit_array = [False] * self.size

    def _optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((m / n) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate multiple hash values for the given item."""
        hashes = []
        for i in range(self.hash_count):
            hash_value = int(hashlib.md5(f"{item}{i}".encode('utf-8')).hexdigest(), 16) % self.size
            hashes.append(hash_value)
        return hashes

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_index in self._hashes(item):
            self.bit_array[hash_index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[hash_index] for hash_index in self._hashes(item))

